{
  "assessment": "The paper reports experimental measurements of 3D and 1D optical lattices formed by a single beam on a grating chip. It provides quantitative controls (beam power, detuning, hold time, modulation frequency), readouts (atom number, cloud size standard deviation, resonance frequencies), and mechanisms (lattice potential, parametric resonance). The data support at least one numeric control, readout, mechanism, and response, so case_authoring_ready is true.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Alan Bregazzi et al., Single-Beam Grating-Chip 3D and 1D Optical Lattices, Physical Review Letters (2025), DOI:10.1103/physrevlett.134.013001",
    "journal_doi": "10.1103/physrevlett.134.013001",
    "arxiv_versioned_id": "2405.21065v2"
  },
  "paper_scope": "The paper demonstrates single-beam grating-chip optical lattices in 3D and 1D, reporting lattice lifetimes, parametric resonance frequencies, and their dependence on beam power and detuning. It includes theoretical trap frequency estimates and experimental measurements for both lattice types.",
  "mechanisms": [
    {
      "mechanism_id": "lattice_potential_3d",
      "statement": "The 3D lattice is formed by a single circularly-polarized 780 nm beam diffracted by a three-sector grating, creating a 3D optical lattice with trap frequencies depending on beam power and detuning.",
      "equations": [
        "nu = A * sqrt(P / Delta)",
        "nu_z = (100 +/- 10) kHz, nu_r = (46 +/- 5) kHz for P=650 mW, Delta=-78 GHz",
        "correction factor sqrt({2,3,4,5,6}/4) for different m_F states"
      ],
      "variable_names": ["nu", "P", "Delta", "nu_z", "nu_r", "m_F"],
      "parameters": [
        {
          "name": "A_3d_resonance",
          "value": 34.2,
          "uncertainty": "not specified",
          "unit": "kHz (GHz/mW)^(1/2)",
          "role": "fitted proportionality constant in nu = A sqrt(P/Delta)",
          "anchors": [
            {
              "line_start": 143,
              "line_end": 143,
              "support": "Fitted value A=34.2 kHz (GHz/mW)^(1/2) for the relation nu = A sqrt(P/Delta)."
            }
          ]
        },
        {
          "name": "nu_z_3d_650mW",
          "value": 100,
          "uncertainty": "standard deviation +/- 10 kHz",
          "unit": "kHz",
          "role": "theoretical axial trap frequency for 3D lattice at P=650 mW, Delta=-78 GHz",
          "anchors": [
            {
              "line_start": 134,
              "line_end": 134,
              "support": "Trap frequencies in the range nu_z=(100 +/- 10) kHz for conditions in Fig. 3a."
            }
          ]
        },
        {
          "name": "nu_r_3d_650mW",
          "value": 46,
          "uncertainty": "standard deviation +/- 5 kHz",
          "unit": "kHz",
          "role": "theoretical radial trap frequency for 3D lattice at P=650 mW, Delta=-78 GHz",
          "anchors": [
            {
              "line_start": 134,
              "line_end": 134,
              "support": "Trap frequencies in the range nu_r=(46 +/- 5) kHz for conditions in Fig. 3a."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "3D lattice uses a single circularly-polarised 780 nm beam, power 0.9 W, e^-2 radius 2.5 mm, red-detuning 78 GHz."
        },
        {
          "line_start": 134,
          "line_end": 135,
          "support": "Theoretical trap frequencies for 3D lattice conditions in Fig. 3a: nu_z=(100 +/- 10) kHz, nu_r=(46 +/- 5) kHz, with correction factor for m_F states."
        },
        {
          "line_start": 143,
          "line_end": 143,
          "support": "Primary resonance frequency follows nu = A sqrt(P/Delta) with A=34.2 kHz (GHz/mW)^(1/2)."
        }
      ]
    },
    {
      "mechanism_id": "lattice_potential_1d",
      "statement": "The 1D lattice is formed by a single linearly-polarised 1070 nm beam, creating a deep far-detuned lattice with trap frequencies nu_z=290 kHz and nu_r=0.9 kHz theoretically, and measured resonances at 200 kHz and 0.5 kHz.",
      "equations": [
        "nu_z_theory = 290 kHz, nu_r_theory = 0.9 kHz",
        "nu_z_measured = 200 kHz, nu_r_measured = 0.5 kHz"
      ],
      "variable_names": ["nu_z", "nu_r"],
      "parameters": [
        {
          "name": "nu_z_1d_theory",
          "value": 290,
          "uncertainty": "not specified",
          "unit": "kHz",
          "role": "theoretical axial trap frequency for 1D lattice",
          "anchors": [
            {
              "line_start": 145,
              "line_end": 145,
              "support": "Expected trap frequencies nu_z=290 kHz and nu_r=0.9 kHz for the 1D lattice."
            }
          ]
        },
        {
          "name": "nu_r_1d_theory",
          "value": 0.9,
          "uncertainty": "not specified",
          "unit": "kHz",
          "role": "theoretical radial trap frequency for 1D lattice",
          "anchors": [
            {
              "line_start": 145,
              "line_end": 145,
              "support": "Expected trap frequencies nu_z=290 kHz and nu_r=0.9 kHz for the 1D lattice."
            }
          ]
        },
        {
          "name": "nu_z_1d_measured",
          "value": 200,
          "uncertainty": "not specified",
          "unit": "kHz",
          "role": "measured axial parametric resonance frequency for 1D lattice",
          "anchors": [
            {
              "line_start": 145,
              "line_end": 145,
              "support": "Measured parametric resonance frequencies in the 1D lattice are nu_z=200 kHz and nu_r=0.5 kHz."
            }
          ]
        },
        {
          "name": "nu_r_1d_measured",
          "value": 0.5,
          "uncertainty": "not specified",
          "unit": "kHz",
          "role": "measured radial parametric resonance frequency for 1D lattice",
          "anchors": [
            {
              "line_start": 145,
              "line_end": 145,
              "support": "Measured parametric resonance frequencies in the 1D lattice are nu_z=200 kHz and nu_r=0.5 kHz."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "1D lattice uses a single linearly-polarised 1070 nm beam, power 10 W, e^-2 radius 80 um."
        },
        {
          "line_start": 145,
          "line_end": 145,
          "support": "Measured parametric resonance frequencies in the 1D lattice are nu_z=200 kHz and nu_r=0.5 kHz, matching sub-harmonics of expected trap frequencies nu_z=290 kHz and nu_r=0.9 kHz."
        }
      ]
    },
    {
      "mechanism_id": "parametric_resonance",
      "statement": "Parametric resonance occurs when the modulation frequency equals twice the trap frequency, causing exponential increase in kinetic energy and atom ejection. Sub-harmonics at 2*nu_trap/n can also be excited.",
      "equations": [
        "f_res = 2 * nu_trap / n, n integer"
      ],
      "variable_names": ["f_res", "nu_trap", "n"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 119,
          "line_end": 119,
          "support": "When modulation frequency equals twice the trapping frequency nu_trap, kinetic energy increases exponentially, and sub-harmonics at 2*nu_trap/n can be excited."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "grating_chip_geometry",
      "statement": "Grating chip with three sectors of 1D diffraction grating, period d=1080 nm, central 4x4 mm^2 area, Al-coated with reflectivity 88% at 780 nm and 95% at 1070 nm.",
      "anchors": [
        {
          "line_start": 72,
          "line_end": 73,
          "support": "Chip comprises three sectors of one-dimensional diffraction grating, period d=1080 nm, Al-coated reflectivity 88% at 780 nm and 95% at 1070 nm."
        }
      ]
    },
    {
      "condition_id": "atom_preparation",
      "statement": "Approximately 8e6 87Rb atoms loaded into GMOT and cooled to ~3 uK via red molasses. Stray DC magnetic fields cancelled by three pairs of Helmholtz coils.",
      "anchors": [
        {
          "line_start": 79,
          "line_end": 79,
          "support": "Approximately 8e6 87Rb atoms loaded into GMOT and cooled to ~3 uK using red molasses. Stray DC magnetic fields cancelled by three pairs of orthogonal Helmholtz coils."
        }
      ]
    },
    {
      "condition_id": "imaging_conditions",
      "statement": "Fluorescence imaging onto CCD, 150 us resonant images after 1 ms time of flight following lattice beam extinction.",
      "anchors": [
        {
          "line_start": 85,
          "line_end": 86,
          "support": "Atom detection via fluorescence imaging onto CCD. 150 us long resonant fluorescent images taken after 1 ms time of flight following extinction of lattice beam."
        }
      ]
    },
    {
      "condition_id": "3d_lattice_beam_parameters",
      "statement": "3D lattice beam: 780 nm, circularly polarised, power 0.9 W, e^-2 radius 2.5 mm, red-detuning 78 GHz from Rb D2 line.",
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "3D lattice uses a single circularly-polarised laser beam at 780 nm, power 0.9 W, e^-2 radius 2.5 mm, red-detuning 78 GHz."
        }
      ]
    },
    {
      "condition_id": "1d_lattice_beam_parameters",
      "statement": "1D lattice beam: 1070 nm, linearly polarised, power 10 W, e^-2 radius 80 um.",
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "1D lattice uses a single linearly-polarised laser beam at 1070 nm, power 10 W, e^-2 radius 80 um."
        }
      ]
    },
    {
      "condition_id": "3d_lattice_modulation_protocol",
      "statement": "For 3D lattice parametric resonance: modulation applied for 50 ms after holding atoms in static lattice for 50 ms, then imaging after 1 ms time of flight.",
      "anchors": [
        {
          "line_start": 121,
          "line_end": 121,
          "support": "In the 3D lattice, modulation is applied for 50 ms after first holding the atoms in the static lattice for 50 ms, then imaged after 1 ms time of flight."
        }
      ]
    },
    {
      "condition_id": "1d_lattice_modulation_protocol",
      "statement": "For 1D lattice parametric resonance: modulation applied for 150 ms.",
      "anchors": [
        {
          "line_start": 121,
          "line_end": 121,
          "support": "In the 1D lattice case, modulation is applied for 150 ms due to improved lattice lifetime."
        }
      ]
    }
  ],
  "controls": [
    {
      "name": "lattice_beam_power",
      "definition": "Optical power of the lattice beam, adjustable via AOM.",
      "unit": "W",
      "minimum": 0.65,
      "maximum": 0.9,
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "3D lattice beam power 0.9 W; 1D lattice beam power 10 W."
        },
        {
          "line_start": 127,
          "line_end": 127,
          "support": "Fig. 3a uses beam power 650 mW for 3D lattice."
        },
        {
          "line_start": 141,
          "line_end": 143,
          "support": "Varied beam powers P for 3D lattice resonance measurements."
        }
      ]
    },
    {
      "name": "lattice_detuning",
      "definition": "Red detuning of the 780 nm lattice beam from the Rb D2 transition.",
      "unit": "GHz",
      "minimum": -78,
      "maximum": -30,
      "anchors": [
        {
          "line_start": 77,
          "line_end": 77,
          "support": "Red-detuning was 78 GHz for the 780 nm lattice."
        },
        {
          "line_start": 127,
          "line_end": 127,
          "support": "Fig. 3b uses detunings Delta=-30, -54, -78 GHz."
        }
      ]
    },
    {
      "name": "modulation_frequency",
      "definition": "Frequency of sinusoidal modulation applied to lattice beam power.",
      "unit": "kHz",
      "minimum": 0,
      "maximum": 200,
      "anchors": [
        {
          "line_start": 119,
          "line_end": 119,
          "support": "Parametric resonance occurs at modulation frequency equal to twice trap frequency."
        },
        {
          "line_start": 131,
          "line_end": 132,
          "support": "Spectrum of cloud standard deviation as a function of modulation frequency shows peak at ~100 kHz."
        },
        {
          "line_start": 145,
          "line_end": 145,
          "support": "Measured 1D lattice resonances at 200 kHz and 0.5 kHz."
        }
      ]
    },
    {
      "name": "hold_time",
      "definition": "Time atoms are held in the lattice before imaging.",
      "unit": "ms",
      "minimum": 0,
      "maximum": 1000,
      "anchors": [
        {
          "line_start": 105,
          "line_end": 107,
          "support": "Number of trapped atoms as a function of hold time, with exponential decays fitted excluding t_hold < 75 ms."
        }
      ]
    }
  ],
  "readouts": [
    {
      "name": "trapped_atom_number",
      "definition": "Number of atoms remaining in the lattice after a given hold time, measured via fluorescence imaging.",
      "unit": "arbitrary",
      "statistic": "count",
      "uncertainty": "not specified",
      "anchors": [
        {
          "line_start": 85,
          "line_end": 86,
          "support": "Atom detection via fluorescence imaging onto CCD."
        },
        {
          "line_start": 105,
          "line_end": 107,
          "support": "Number of trapped atoms as a function of hold time, fitted with exponential decays."
        }
      ]
    },
    {
      "name": "cloud_standard_deviation",
      "definition": "Spatial standard deviation of the atomic cloud distribution after modulation, indicating vibrational heating.",
      "unit": "mm",
      "statistic": "standard deviation",
      "uncertainty": "not specified",
      "anchors": [
        {
          "line_start": 127,
          "line_end": 127,
          "support": "Experimental standard deviation sigma of the 3D lattice cloud distribution, showing spectrum of vibrational heating (sigma > 0.44 mm)."
        }
      ]
    },
    {
      "name": "primary_resonance_frequency",
      "definition": "Frequency of the primary parametric resonance peak observed in the heating spectrum.",
      "unit": "kHz",
      "statistic": "peak frequency",
      "uncertainty": "not specified",
      "anchors": [
        {
          "line_start": 131,
          "line_end": 132,
          "support": "Clear primary peak at around 100 kHz in the 3D lattice spectrum."
        },
        {
          "line_start": 141,
          "line_end": 143,
          "support": "Primary observed resonance frequency plotted as a function of P/Delta."
        }
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "3d_lattice_lifetime",
      "statement": "The 3D lattice has an estimated lifetime of 54 ms, fitted from exponential decay of atom number versus hold time.",
      "quantitative_form": "N(t) = N0 * exp(-t / tau_3d), tau_3d = 54 ms",
      "mechanism_ids": ["lattice_potential_3d"],
      "control_names": ["hold_time"],
      "readout_names": ["trapped_atom_number"],
      "fixed_condition_ids": ["3d_lattice_beam_parameters", "atom_preparation", "imaging_conditions"],
      "applicability": "For 3D lattice with beam power 0.9 W, detuning -78 GHz, hold times > 75 ms.",
      "statistical_basis": "Exponential decay fit to atom number data, excluding t_hold < 75 ms.",
      "uncertainty": "Not specified.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 101,
          "line_end": 101,
          "support": "Fitted exponential decays reveal estimated lattice lifetimes of 54 ms for the 3D lattice."
        },
        {
          "line_start": 105,
          "line_end": 107,
          "support": "Exponential decays fitted excluding t_hold < 75 ms to eliminate untrapped atoms."
        }
      ]
    },
    {
      "claim_id": "1d_lattice_lifetime",
      "statement": "The 1D lattice has an estimated lifetime of 220 ms, fitted from exponential decay of atom number versus hold time.",
      "quantitative_form": "N(t) = N0 * exp(-t / tau_1d), tau_1d = 220 ms",
      "mechanism_ids": ["lattice_potential_1d"],
      "control_names": ["hold_time"],
      "readout_names": ["trapped_atom_number"],
      "fixed_condition_ids": ["1d_lattice_beam_parameters", "atom_preparation", "imaging_conditions"],
      "applicability": "For 1D lattice with beam power 10 W, hold times > 75 ms.",
      "statistical_basis": "Exponential decay fit to atom number data, excluding t_hold < 75 ms.",
      "uncertainty": "Not specified.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 101,
          "line_end": 101,
          "support": "Fitted exponential decays reveal estimated lattice lifetimes of 220 ms for the 1D lattice."
        },
        {
          "line_start": 112,
          "line_end": 112,
          "support": "Fitting an exponential decay to lattice atom number data indicates a longer trap lifetime of 220 ms."
        }
      ]
    },
    {
      "claim_id": "3d_resonance_frequency_vs_power_detuning",
      "statement": "The primary 3D lattice resonance frequency follows nu = A * sqrt(P/Delta) with A = 34.2 kHz (GHz/mW)^(1/2).",
      "quantitative_form": "nu = 34.2 * sqrt(P / Delta) kHz, with P in mW and Delta in GHz",
      "mechanism_ids": ["lattice_potential_3d", "parametric_resonance"],
      "control_names": ["lattice_beam_power", "lattice_detuning"],
      "readout_names": ["primary_resonance_frequency"],
      "fixed_condition_ids": ["3d_lattice_beam_parameters", "3d_lattice_modulation_protocol"],
      "applicability": "For 3D lattice with detunings -30, -54, -78 GHz and powers varied; P/Delta in units of mW/GHz.",
      "statistical_basis": "Fitted relation to experimental resonance data for various powers and detunings.",
      "uncertainty": "Not specified for A.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 141,
          "line_end": 143,
          "support": "By plotting primary observed resonance frequency as a function of P/Delta, data follow nu = A sqrt(P/Delta) with A=34.2 kHz (GHz/mW)^(1/2)."
        }
      ]
    },
    {
      "claim_id": "3d_resonance_spectrum_650mW",
      "statement": "For the 3D lattice at 650 mW and -78 GHz detuning, the primary resonance is at ~100 kHz with a secondary feature at ~50 kHz, matching theoretical trap frequencies nu_z=(100 +/- 10) kHz and nu_r=(46 +/- 5) kHz.",
      "quantitative_form": "nu_primary ~ 100 kHz, nu_secondary ~ 50 kHz; theory nu_z=100 kHz, nu_r=46 kHz",
      "mechanism_ids": ["lattice_potential_3d", "parametric_resonance"],
      "control_names": ["modulation_frequency"],
      "readout_names": ["cloud_standard_deviation", "primary_resonance_frequency"],
      "fixed_condition_ids": ["3d_lattice_beam_parameters", "3d_lattice_modulation_protocol"],
      "applicability": "For 3D lattice with beam power 650 mW and detuning -78 GHz.",
      "statistical_basis": "Experimental spectrum of cloud standard deviation; theoretical trap frequencies with standard deviations.",
      "uncertainty": "Theoretical nu_z +/- 10 kHz, nu_r +/- 5 kHz; experimental peak positions approximate.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 131,
          "line_end": 132,
          "support": "Clear primary peak at around 100 kHz, with a partially-resolved secondary feature at around 50 kHz."
        },
        {
          "line_start": 134,
          "line_end": 134,
          "support": "For conditions in Fig. 3a, trap frequencies in range nu_z=(100 +/- 10) kHz and nu_r=(46 +/- 5) kHz."
        }
      ]
    },
    {
      "claim_id": "1d_resonance_frequencies",
      "statement": "Measured parametric resonance frequencies in the 1D lattice are nu_z=200 kHz and nu_r=0.5 kHz, matching sub-harmonics of expected trap frequencies nu_z=290 kHz and nu_r=0.9 kHz.",
      "quantitative_form": "nu_z_measured = 200 kHz, nu_r_measured = 0.5 kHz; theory nu_z=290 kHz, nu_r=0.9 kHz",
      "mechanism_ids": ["lattice_potential_1d", "parametric_resonance"],
      "control_names": ["modulation_frequency"],
      "readout_names": ["primary_resonance_frequency"],
      "fixed_condition_ids": ["1d_lattice_beam_parameters", "1d_lattice_modulation_protocol"],
      "applicability": "For 1D lattice with beam power 10 W.",
      "statistical_basis": "Experimental spectra of atom loss; theoretical trap frequencies.",
      "uncertainty": "Not specified; signal-to-noise low.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 145,
          "line_end": 145,
          "support": "Measured parametric resonance frequencies in the 1D lattice are nu_z=200 kHz and nu_r=0.5 kHz, matching sub-harmonics of expected trap frequencies nu_z=290 kHz and nu_r=0.9 kHz."
        }
      ]
